//! The radial functions: power-series solutions of the paper's radial equation with a source,
//!
//! ```text
//! 4 R**2 d2X/d(R**2)**2 + (k_max**2 - k_j**2 + p_prime_term (R**2 - R_c**2)) X = s(R**2),
//! ```
//!
//! with `p_prime_term = (2 pi)**2 mu0 c_bar_p_prime / (psi_a - psi_b)`, generated by an explicit recursion, as the paper's `C_j` and
//! `S_j`.
//!
//! Two radial variables are available, the paper's powers of `R**2 - R_c**2` and of `ln(R**2 / R_c**2)`. Each is scaled to -1 and +1 at
//! the plasma's innermost and outermost `R`, `R_geo - a_minor` and `R_geo + a_minor`, so that the powers up to `n_radial` stay within
//! double precision whatever the size of the machine; this scaled radial variable is `radial`.
//!
//! * `RadialVariableKind::RSquared`: `radial = (R**2 - R_c**2) / (2 R_geo a_minor)`, `2 R_geo a_minor` being the plasma's half-width in
//!   `R**2`. `X = sum_m d_m radial**m` and, with `L = 2 R_geo a_minor` (the paper's recursion with `d_m` scaled by `L**m`),
//!   `d_{m+2} = (L**2 s_m - 4 m (m + 1) L d_{m+1} - (k_max**2 - k_j**2) L**2 d_m - p_prime_term L**3 d_{m-1}) / (4 R_c**2 (m + 1)(m + 2))`.
//!   Its radius of convergence is `R_c**2` in `R**2` (the line `R = 0`), so near the inboard edge the terms fall like
//!   `(2 R_geo a_minor / R_c**2)**m`: `0.6**m` for the elongated D, but `0.96**m` for a spherical tokamak with
//!   `a_minor / R_geo = 0.75`.
//! * `RadialVariableKind::LogRSquared`: `radial = (t - log_centre) / log_half_width`, `t = ln(R**2 / R_c**2)`, with `log_centre` the
//!   middle of the plasma's range of `t` and `log_half_width` its half-width. Every solution of the radial equation is entire in `t`,
//!   since `R = 0` moves to `t = -infinity`. In `t` the equation is
//!   `X_tt - X_t + (R_c**2 / 4) e**t (k_max**2 - k_j**2 - p_prime_term R_c**2) X + (p_prime_term R_c**4 / 4) e**(2 t) X
//!   = (R_c**2 / 4) e**t s`, and in `radial`, with `w = log_half_width`, the recursion is
//!   `(m + 2)(m + 1) d_{m+2} = w**2 f_m + w (m + 1) d_{m+1} - w**2 sum_n (a w**n / n! + b (2 w)**n / n!) d_{m-n}`, with
//!   `a = (R_c**2 / 4) e**log_centre (k_max**2 - k_j**2 - p_prime_term R_c**2)`, `b = (p_prime_term R_c**4 / 4) e**(2 log_centre)` and
//!   `f_m` the coefficients of `(R_c**2 / 4) e**t s`.
//!
//! Coefficients are complex: the radial functions of the products of `cos` and `cosh` terms, whose `k_j**2` is complex, are complex,
//! and real ones simply have zero imaginary parts.

use super::double_double::{DoubleDouble, sum_pairwise};
use super::numerics::{GaussLegendre, complex_divide, gauss_legendre};
use faer::c64;
use ndarray::{Array1, Array2, ArrayView1, ArrayView2};
use rayon::prelude::*;

/// Growth across the plasma, in e-folds, up to which a hyperbolic wavenumber's minimum-norm particular solution is computed in double
/// precision: its bounded response is about `s / (k_j**2 - k_max**2)`, but finding it by projection cancels terms `exp(growth)` times
/// larger, so double precision keeps `16 - growth / 2.3` digits of it (1e-5 of the mode at 27 e-folds, against 60-digit arithmetic).
/// 27 e-folds is `k_j = 42 / metre`, 9 `k_max`, on the elongated D [dimensionless]
pub const GROWTH_MAX: f64 = 27.0;

/// Growth up to which the stronger hyperbolic wavenumbers are computed in double-double arithmetic (`min_norm_particular_extended`, 32
/// digits: 1e-15 of the mode up to about 40 e-folds and 1e-12 at 48, against 80-digit arithmetic); wavenumbers beyond it get no
/// particular solution [dimensionless]
pub const GROWTH_MAX_EXTENDED: f64 = 50.0;

/// Gauss-Legendre nodes on each side of the expansion point for the WKB growth estimate `log_growth` [dimensionless]
const N_GROWTH_NODE: usize = 64;

/// The last powers of a radial power series whose change of `(1 - psi_N)` on the plasma measures its truncation (`radial_tolerance`)
/// [dimensionless]
pub const N_RADIAL_TAIL: usize = 10;

/// The fewest terms in a radial power series (`n_radial`) [dimensionless]
pub const N_RADIAL_MIN: usize = 2 * N_RADIAL_TAIL;

/// The kind of radial variable: the paper's powers of `R**2 - R_c**2` or of `ln(R**2 / R_c**2)`
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RadialVariableKind {
    /// `(R**2 - R_c**2) / (2 R_geo a_minor)`
    RSquared,
    /// `(ln(R**2 / R_c**2) - log_centre) / log_half_width`, in which the radial functions are entire (spherical tokamaks)
    LogRSquared,
}

impl RadialVariableKind {
    /// Its name in the options, the input `radial_variable`: `r_squared` or `log_r_squared`
    pub fn name(&self) -> &'static str {
        match self {
            RadialVariableKind::RSquared => "r_squared",
            RadialVariableKind::LogRSquared => "log_r_squared",
        }
    }
}

/// Where the power series can be evaluated
#[derive(Clone, Copy, Debug)]
pub struct ValidRange {
    /// Inboard end [metre]
    pub r_minimum: f64,
    /// Outboard end [metre]
    pub r_maximum: f64,
}

/// `d(radial)/dR` and `d2(radial)/dR**2`, for the chain rule `d2X/dR**2 = (d(radial)/dR)**2 X_radial,radial + d2(radial)/dR**2 X_radial`
#[derive(Clone, Copy, Debug)]
pub struct RadialDerivatives {
    /// [1 / metre]
    pub d_radial_d_r: f64,
    /// [1 / metre ** 2]
    pub d2_radial_d_r2: f64,
}

/// `constant + slope (R**2 - R_c**2)` written in the scaled radial variable: `one + other radial` in `R**2`, `one + other exp(w radial)`
/// in `ln(R**2 / R_c**2)`
#[derive(Clone, Copy, Debug)]
pub struct LinearFunctionInRadial {
    /// The coefficient of 1 [same unit as `constant`]
    pub coefficient_one: f64,
    /// The coefficient of `radial` (in `R**2`) or of `exp(w radial)` (in `ln(R**2 / R_c**2)`) [same unit as `constant`]
    pub coefficient_other: f64,
}

/// The paper's homogeneous radial functions of one wavenumber, with their data at `R = R_c`
pub struct RadialPair {
    /// `C_j`: `X = 1`, `dX/d(radial) = 0` at `R_c`; power-series coefficients in `radial` [dimensionless]
    pub c: Array1<c64>,
    /// `S_j`: `X = 0`, `dX/d(radial) = 1` at `R_c`, the paper's `S_j` times `2 R_geo a_minor` (as the paper plots it) [dimensionless]
    pub s: Array1<c64>,
}

/// The scaled radial variable of the power series, with the series of `exp(w radial)` for the products and the Gauss-Legendre rule of
/// the minimum-norm projections.
pub struct RadialVariable {
    pub kind: RadialVariableKind,
    /// Number of terms in every radial power series [dimensionless]
    pub n_radial: usize,
    /// The paper's `R_geo` [metre]
    pub r_geo: f64,
    /// The paper's `a_minor` [metre]
    pub a_minor: f64,
    /// `R_c**2 = R_geo**2 + a_minor**2` [metre ** 2]
    pub r_c_squared: f64,
    /// `2 R_geo a_minor`, the plasma's half-width in `R**2` about `R_c**2` [metre ** 2]
    pub r_squared_half_width: f64,
    /// The middle of the plasma's range of `ln(R**2 / R_c**2)`, `ln((R_geo - a_minor) (R_geo + a_minor) / R_c**2)`; 0 in `R**2`
    /// [dimensionless]
    pub log_centre: f64,
    /// Its half-width, `w = ln((R_geo + a_minor) / (R_geo - a_minor))`; 1 in `R**2` [dimensionless]
    pub log_half_width: f64,
    /// Taylor coefficients of `exp(w radial)`, `w**n / n!` [dimensionless]
    pub exp_series: Array1<f64>,
    /// Taylor coefficients of `exp(2 w radial)` [dimensionless]
    pub exp2_series: Array1<f64>,
    /// Gauss-Legendre nodes in `R**2` across the plasma, from `(R_geo - a_minor)**2` to `(R_geo + a_minor)**2`, for the minimum-norm
    /// projections, `2 n_radial + 40` of them [metre ** 2]
    pub quadrature_r_squared: Array1<f64>,
    /// Their weights [metre ** 2]
    pub quadrature_weights: Array1<f64>,
    /// `radial**m` at the nodes, shape `(n_node, n_radial)` [dimensionless]
    pub quadrature_vandermonde: Array2<f64>,
    /// The rule of `log_growth` [dimensionless]
    pub growth_quadrature: GaussLegendre,
}

impl RadialVariable {
    /// # Arguments
    /// * `r_geo` - the paper's `R_geo` [metre]
    /// * `a_minor` - the paper's `a_minor`, less than `r_geo` [metre]
    /// * `kind` - powers of `R**2 - R_c**2`, or of `ln(R**2 / R_c**2)` (entire radial functions; for spherical tokamaks)
    /// * `n_radial` - number of terms in every radial power series [dimensionless]
    pub fn new(r_geo: f64, a_minor: f64, kind: RadialVariableKind, n_radial: usize) -> RadialVariable {
        let mut radial_variable: RadialVariable = RadialVariable::without_quadrature(r_geo, a_minor, kind, n_radial);
        // Taylor coefficients of exp(w radial) and exp(2 w radial), by the recursion w**n / n! = w**(n - 1) / (n - 1)! * w / n
        let log_half_width: f64 = radial_variable.log_half_width;
        let mut exp_series: Array1<f64> = Array1::from_elem(n_radial, f64::NAN);
        let mut exp2_series: Array1<f64> = Array1::from_elem(n_radial, f64::NAN);
        for i_radial in 0..n_radial {
            if i_radial == 0 {
                exp_series[i_radial] = 1.0;
                exp2_series[i_radial] = 1.0;
            } else {
                exp_series[i_radial] = exp_series[i_radial - 1] * log_half_width / (i_radial as f64);
                exp2_series[i_radial] = exp2_series[i_radial - 1] * (2.0 * log_half_width) / (i_radial as f64);
            }
        }
        radial_variable.exp_series = exp_series;
        radial_variable.exp2_series = exp2_series;
        // Gauss-Legendre nodes in R**2 across the plasma, for the minimum-norm projections (exact in R**2 for polynomials of degree
        // 2 n_radial + 79)
        let n_node: usize = 2 * n_radial + 40;
        let quadrature: GaussLegendre = gauss_legendre(n_node);
        let r_c_squared: f64 = radial_variable.r_c_squared;
        let r_squared_half_width: f64 = radial_variable.r_squared_half_width;
        let quadrature_r_squared: Array1<f64> = quadrature.nodes.mapv(|node: f64| r_c_squared + r_squared_half_width * node);
        let quadrature_weights: Array1<f64> = quadrature.weights.mapv(|weight: f64| r_squared_half_width * weight);
        let mut vandermonde: Array2<f64> = Array2::from_elem((n_node, n_radial), f64::NAN);
        for i_node in 0..n_node {
            let radial: f64 = radial_variable.of_r_squared(quadrature_r_squared[i_node]);
            let mut power: f64 = 1.0;
            for i_radial in 0..n_radial {
                vandermonde[[i_node, i_radial]] = power;
                power *= radial;
            }
        }
        radial_variable.quadrature_r_squared = quadrature_r_squared;
        radial_variable.quadrature_weights = quadrature_weights;
        radial_variable.quadrature_vandermonde = vandermonde;
        radial_variable.growth_quadrature = gauss_legendre(N_GROWTH_NODE);
        radial_variable
    }

    /// The radial variable without its series or quadrature: enough to map `R` to `radial` and back
    fn without_quadrature(r_geo: f64, a_minor: f64, kind: RadialVariableKind, n_radial: usize) -> RadialVariable {
        let r_c_squared: f64 = r_geo * r_geo + a_minor * a_minor;
        let r_squared_half_width: f64 = 2.0 * r_geo * a_minor;
        let mut log_centre: f64 = 0.0;
        let mut log_half_width: f64 = 1.0;
        if kind == RadialVariableKind::LogRSquared {
            // ln(R**2 / R_c**2) runs from ln(1 - L / R_c**2) to ln(1 + L / R_c**2), L = 2 R_geo a_minor
            let half_width_ratio: f64 = r_squared_half_width / r_c_squared;
            log_centre = 0.5 * (1.0 - half_width_ratio * half_width_ratio).ln();
            log_half_width = half_width_ratio.atanh();
        }
        RadialVariable {
            kind,
            n_radial,
            r_geo,
            a_minor,
            r_c_squared,
            r_squared_half_width,
            log_centre,
            log_half_width,
            exp_series: Array1::zeros(0),
            exp2_series: Array1::zeros(0),
            quadrature_r_squared: Array1::zeros(0),
            quadrature_weights: Array1::zeros(0),
            quadrature_vandermonde: Array2::zeros((0, 0)),
            growth_quadrature: GaussLegendre {
                nodes: Array1::zeros(0),
                weights: Array1::zeros(0),
            },
        }
    }

    /// # Arguments
    /// * `r_squared` - `R**2`, positive [metre ** 2]
    ///
    /// # Returns
    /// * the scaled radial variable [dimensionless]
    pub fn of_r_squared(&self, r_squared: f64) -> f64 {
        match self.kind {
            RadialVariableKind::LogRSquared => ((r_squared / self.r_c_squared).ln() - self.log_centre) / self.log_half_width,
            RadialVariableKind::RSquared => (r_squared - self.r_c_squared) / self.r_squared_half_width,
        }
    }

    /// # Arguments
    /// * `r` - major radius, positive [metre]
    ///
    /// # Returns
    /// * the scaled radial variable [dimensionless]
    pub fn of_r(&self, r: f64) -> f64 {
        self.of_r_squared(r * r)
    }

    /// # Arguments
    /// * `radial` - the scaled radial variable [dimensionless]
    ///
    /// # Returns
    /// * `R**2` [metre ** 2]
    pub fn to_r_squared(&self, radial: f64) -> f64 {
        match self.kind {
            RadialVariableKind::LogRSquared => self.r_c_squared * (self.log_half_width * radial + self.log_centre).exp(),
            RadialVariableKind::RSquared => self.r_c_squared + self.r_squared_half_width * radial,
        }
    }

    /// # Arguments
    /// * `radial` - the scaled radial variable [dimensionless]
    ///
    /// # Returns
    /// * `R` [metre]
    pub fn to_r(&self, radial: f64) -> f64 {
        self.to_r_squared(radial).sqrt()
    }

    /// Where the power series can be evaluated: in `R**2`, within 98 % of the radius of convergence `R_c**2` (the line `R = 0`); in
    /// `ln(R**2 / R_c**2)`, for `|radial| <= 1.1`, beyond which the rounding noise of the products, about `1e-16` of the largest
    /// coefficient in every power, grows like `|radial|**n_radial`.
    pub fn r_range_valid(&self) -> ValidRange {
        match self.kind {
            RadialVariableKind::LogRSquared => ValidRange {
                r_minimum: self.to_r(-1.1),
                r_maximum: self.to_r(1.1),
            },
            RadialVariableKind::RSquared => ValidRange {
                r_minimum: (0.02 * self.r_c_squared).sqrt(),
                r_maximum: (1.98 * self.r_c_squared).sqrt(),
            },
        }
    }

    /// `r_range_valid` of a radial variable of this kind, without building its quadrature (only `R_geo`, `a_minor` and the kind matter)
    pub fn valid_range(r_geo: f64, a_minor: f64, kind: RadialVariableKind) -> ValidRange {
        RadialVariable::without_quadrature(r_geo, a_minor, kind, 0).r_range_valid()
    }

    /// `(d(radial)/dR, d2(radial)/dR**2)` at `R`
    pub fn derivatives_of_radial(&self, r: f64) -> RadialDerivatives {
        match self.kind {
            RadialVariableKind::LogRSquared => RadialDerivatives {
                d_radial_d_r: 2.0 / (self.log_half_width * r),
                d2_radial_d_r2: -2.0 / (self.log_half_width * r * r),
            },
            RadialVariableKind::RSquared => RadialDerivatives {
                d_radial_d_r: 2.0 * r / self.r_squared_half_width,
                d2_radial_d_r2: 2.0 / self.r_squared_half_width,
            },
        }
    }

    /// `constant + slope (R**2 - R_c**2)` in the scaled radial variable: `constant + slope L radial` in `R**2`, and `A + B exp(w radial)`
    /// in `ln(R**2 / R_c**2)`, since `R**2 - R_c**2 = R_c**2 (e**log_centre e**(w radial) - 1)`.
    ///
    /// # Arguments
    /// * `constant` - [any unit]
    /// * `slope` - [same unit / metre ** 2]
    pub fn linear_function_coefficients(&self, constant: f64, slope: f64) -> LinearFunctionInRadial {
        match self.kind {
            RadialVariableKind::LogRSquared => LinearFunctionInRadial {
                coefficient_one: constant - slope * self.r_c_squared,
                coefficient_other: slope * self.r_c_squared * self.log_centre.exp(),
            },
            RadialVariableKind::RSquared => LinearFunctionInRadial {
                coefficient_one: constant,
                coefficient_other: slope * self.r_squared_half_width,
            },
        }
    }
}

/// The power-series solution of `4 R**2 d2X/d(R**2)**2 + (k_max**2 - k_j**2 + p_prime_term (R**2 - R_c**2)) X = s(R**2)` with the data
/// `X = value_0`, `dX/d(radial) = slope_0` at `radial = 0` (the expansion point: `R_c` in `R**2`, the middle of the plasma in
/// `ln(R**2 / R_c**2)`).
///
/// # Arguments
/// * `radial` - the radial variable
/// * `source` - coefficients of `s` in `radial`, `n_radial` of them [1 / metre ** 2]
/// * `k_max_squared_minus_k_squared` - `k_max**2 - k_j**2`; complex for complex `k_j` [1 / metre ** 2]
/// * `p_prime_term` - `(2 pi)**2 mu0 c_bar_p_prime / (psi_a - psi_b)` [1 / metre ** 4]
/// * `value_0` - `X(radial = 0)` [dimensionless]
/// * `slope_0` - `dX/d(radial)(radial = 0)` [dimensionless]
///
/// # Returns
/// * coefficients of `X` in `radial`, `n_radial` of them [dimensionless]
pub fn solve_radial_ode(
    radial: &RadialVariable,
    source: ArrayView1<c64>,
    k_max_squared_minus_k_squared: c64,
    p_prime_term: f64,
    value_0: c64,
    slope_0: c64,
) -> Array1<c64> {
    let n_radial: usize = radial.n_radial;
    let r_c_squared: f64 = radial.r_c_squared;
    let mut coefficients: Array1<c64> = Array1::from_elem(n_radial, c64::new(f64::NAN, f64::NAN));
    coefficients[0] = value_0;
    coefficients[1] = slope_0;
    match radial.kind {
        RadialVariableKind::LogRSquared => {
            let log_half_width: f64 = radial.log_half_width;
            let exp_centre: f64 = radial.log_centre.exp();
            // w**2 (R_c**2 / 4) e**log_centre, the factor of the e**t terms
            let factor: f64 = log_half_width * log_half_width * 0.25 * r_c_squared * exp_centre;
            let coefficient_a: c64 = (k_max_squared_minus_k_squared - p_prime_term * r_c_squared) * factor;
            let coefficient_b: f64 = log_half_width * log_half_width * 0.25 * p_prime_term * r_c_squared * r_c_squared * (exp_centre * exp_centre);
            for i_radial in 0..n_radial - 2 {
                // The source's Cauchy product with exp(w radial), then its factor
                let mut source_with_exp: c64 = c64::new(0.0, 0.0);
                for j_radial in 0..=i_radial {
                    source_with_exp += source[j_radial] * radial.exp_series[i_radial - j_radial];
                }
                let forcing: c64 = source_with_exp * factor;
                // Cauchy products of d[0..m] with the series of exp(w radial) and exp(2 w radial), newest coefficient first
                let mut convolution_a: c64 = c64::new(0.0, 0.0);
                let mut convolution_b: c64 = c64::new(0.0, 0.0);
                for j_radial in 0..=i_radial {
                    convolution_a += coefficients[i_radial - j_radial] * radial.exp_series[j_radial];
                    convolution_b += coefficients[i_radial - j_radial] * radial.exp2_series[j_radial];
                }
                let power: f64 = i_radial as f64;
                coefficients[i_radial + 2] =
                    (forcing + coefficients[i_radial + 1] * (log_half_width * (power + 1.0)) - coefficient_a * convolution_a - convolution_b * coefficient_b)
                        / ((power + 1.0) * (power + 2.0));
            }
        }
        RadialVariableKind::RSquared => {
            let half_width: f64 = radial.r_squared_half_width;
            let half_width_squared: f64 = half_width * half_width;
            for i_radial in 0..n_radial - 2 {
                let power: f64 = i_radial as f64;
                let previous: c64 = if i_radial >= 1 { coefficients[i_radial - 1] } else { c64::new(0.0, 0.0) };
                coefficients[i_radial + 2] = (source[i_radial] * half_width_squared
                    - coefficients[i_radial + 1] * (4.0 * power * (power + 1.0) * half_width)
                    - k_max_squared_minus_k_squared * half_width_squared * coefficients[i_radial]
                    - previous * (p_prime_term * half_width_squared * half_width))
                    / (4.0 * r_c_squared * (power + 1.0) * (power + 2.0));
            }
        }
    }
    coefficients
}

/// The paper's homogeneous radial functions of one wavenumber: `C_j` with `X = 1`, `dX/d(radial) = 0`, and `S_j` with `X = 0`,
/// `dX/d(radial) = 1` at `R = R_c`.
///
/// In `R**2` these are single recursions from `R_c`. In `ln(R**2 / R_c**2)` they combine the two solutions with unit data at
/// `radial = 0`, so that their data at `R_c` are the paper's (the slope in the scaled `R**2`, `(R**2 - R_c**2) / (2 R_geo a_minor)`).
///
/// # Arguments
/// * `radial` - the radial variable
/// * `k_max_squared_minus_k_squared` - the wavenumber's `k_max**2 - k_j**2` [1 / metre ** 2]
/// * `p_prime_term` - `(2 pi)**2 mu0 c_bar_p_prime / (psi_a - psi_b)` [1 / metre ** 4]
pub fn c_and_s(radial: &RadialVariable, k_max_squared_minus_k_squared: c64, p_prime_term: f64) -> RadialPair {
    let n_radial: usize = radial.n_radial;
    let zero_source: Array1<c64> = Array1::from_elem(n_radial, c64::new(0.0, 0.0));
    let one: c64 = c64::new(1.0, 0.0);
    let zero: c64 = c64::new(0.0, 0.0);
    let unit_value: Array1<c64> = solve_radial_ode(radial, zero_source.view(), k_max_squared_minus_k_squared, p_prime_term, one, zero);
    let unit_slope: Array1<c64> = solve_radial_ode(radial, zero_source.view(), k_max_squared_minus_k_squared, p_prime_term, zero, one);
    if radial.kind == RadialVariableKind::RSquared {
        return RadialPair { c: unit_value, s: unit_slope };
    }
    let radial_at_r_c: f64 = radial.of_r_squared(radial.r_c_squared);
    // d(radial) / d((R**2 - R_c**2) / (2 R_geo a_minor)) at R_c
    let d_radial_d_scaled_r_squared: f64 = radial.r_squared_half_width / (radial.r_c_squared * radial.log_half_width);
    // Values and slopes at R_c of the unit-data solutions; [[v1, v2], [s1, s2]] (w1, w2) = target
    let mut value_1: c64 = c64::new(0.0, 0.0);
    let mut value_2: c64 = c64::new(0.0, 0.0);
    let mut slope_1_radial: c64 = c64::new(0.0, 0.0);
    let mut slope_2_radial: c64 = c64::new(0.0, 0.0);
    for i_radial in 0..n_radial {
        let power_at_r_c: f64 = radial_at_r_c.powf(i_radial as f64);
        value_1 += unit_value[i_radial] * power_at_r_c;
        value_2 += unit_slope[i_radial] * power_at_r_c;
        if i_radial >= 1 {
            let power_at_r_c_d1: f64 = (i_radial as f64) * radial_at_r_c.powf((i_radial - 1) as f64);
            slope_1_radial += unit_value[i_radial] * power_at_r_c_d1;
            slope_2_radial += unit_slope[i_radial] * power_at_r_c_d1;
        }
    }
    let slope_1: c64 = slope_1_radial * d_radial_d_scaled_r_squared;
    let slope_2: c64 = slope_2_radial * d_radial_d_scaled_r_squared;
    let determinant: c64 = value_1 * slope_2 - value_2 * slope_1;
    // C: value 1, slope 0; S: value 0, slope 1
    let c_value: c64 = complex_divide(slope_2, determinant);
    let c_slope: c64 = complex_divide(-slope_1, determinant);
    let s_value: c64 = complex_divide(-value_2, determinant);
    let s_slope: c64 = complex_divide(value_1, determinant);
    let mut c: Array1<c64> = Array1::from_elem(n_radial, c64::new(f64::NAN, f64::NAN));
    let mut s: Array1<c64> = Array1::from_elem(n_radial, c64::new(f64::NAN, f64::NAN));
    for i_radial in 0..n_radial {
        c[i_radial] = c_value * unit_value[i_radial] + c_slope * unit_slope[i_radial];
        s[i_radial] = s_value * unit_value[i_radial] + s_slope * unit_slope[i_radial];
    }
    RadialPair { c, s }
}

/// WKB estimate of how many e-folds a homogeneous radial solution grows from the expansion point to the farther plasma edge,
/// `max(int_{R_0**2}^{R_out**2}, int_{R_in**2}^{R_0**2}) |Re sqrt(-(k_max**2 - k_j**2 + p_prime_term (R**2 - R_c**2)) / (4 R**2))|
/// d(R**2)`, with `R_0` the expansion point and `R_in`, `R_out` the plasma's innermost and outermost `R`.
///
/// # Arguments
/// * `radial` - the radial variable
/// * `k_max_squared_minus_k_squared` - the wavenumber's `k_max**2 - k_j**2` [1 / metre ** 2]
/// * `p_prime_term` - `(2 pi)**2 mu0 c_bar_p_prime / (psi_a - psi_b)` [1 / metre ** 4]
///
/// # Returns
/// * the growth, 0 for oscillatory modes [dimensionless]
pub fn log_growth(radial: &RadialVariable, k_max_squared_minus_k_squared: c64, p_prime_term: f64) -> f64 {
    let r_squared_0: f64 = radial.to_r_squared(0.0);
    let r_squared_inner: f64 = radial.r_c_squared - radial.r_squared_half_width;
    let r_squared_outer: f64 = radial.r_c_squared + radial.r_squared_half_width;
    let nodes: &Array1<f64> = &radial.growth_quadrature.nodes;
    let weights: &Array1<f64> = &radial.growth_quadrature.weights;
    let n_node: usize = nodes.len();
    let sides: [(f64, f64); 2] = [(r_squared_inner, r_squared_0), (r_squared_0, r_squared_outer)];
    let mut growth: f64 = 0.0;
    for (side_low, side_high) in sides {
        let half_width: f64 = 0.5 * (side_high - side_low);
        let mut side_sum: f64 = 0.0;
        for i_node in 0..n_node {
            let r_squared_node: f64 = 0.5 * (side_high + side_low) + half_width * nodes[i_node];
            // The local WKB exponent; its real part is the growth rate (k_j**2 may be complex)
            let exponent: c64 = (-(k_max_squared_minus_k_squared + p_prime_term * (r_squared_node - radial.r_c_squared)) / (4.0 * r_squared_node)).sqrt();
            side_sum += exponent.re.abs() * weights[i_node];
        }
        // NaN propagates, so that a mode with a NaN k_j**2 is dropped rather than taken as oscillatory
        let side_growth: f64 = half_width * side_sum;
        if side_growth.is_nan() || side_growth > growth {
            growth = side_growth;
        }
    }
    growth
}

/// The values of a radial power series at the projection's Gauss-Legendre nodes, times the square roots of the weights
fn weighted_node_values(radial: &RadialVariable, coefficients: ArrayView1<c64>, root_weights: ArrayView1<f64>) -> Array1<c64> {
    let n_node: usize = radial.quadrature_r_squared.len();
    let n_radial: usize = radial.n_radial;
    let mut values: Array1<c64> = Array1::from_elem(n_node, c64::new(f64::NAN, f64::NAN));
    for i_node in 0..n_node {
        let mut value_re: f64 = 0.0;
        let mut value_im: f64 = 0.0;
        for i_radial in 0..n_radial {
            let power: f64 = radial.quadrature_vandermonde[[i_node, i_radial]];
            value_re += coefficients[i_radial].re * power;
            value_im += coefficients[i_radial].im * power;
        }
        values[i_node] = c64::new(value_re, value_im) * root_weights[i_node];
    }
    values
}

/// `sum conj(first) second`
fn hermitian_inner(first: &Array1<c64>, second: &Array1<c64>) -> c64 {
    let n_value: usize = first.len();
    let mut total: c64 = c64::new(0.0, 0.0);
    for i_value in 0..n_value {
        total += first[i_value].conj() * second[i_value];
    }
    total
}

/// `sum |values|**2`
fn squared_norm(values: &Array1<c64>) -> f64 {
    let n_value: usize = values.len();
    let mut total: f64 = 0.0;
    for i_value in 0..n_value {
        let magnitude: f64 = values[i_value].norm();
        total += magnitude * magnitude;
    }
    total
}

/// The homogeneous solutions of the radial equation for one wavenumber, and the QR factors of their weighted values at the
/// Gauss-Legendre nodes: what the minimum-norm projection of any forced solution of the same wavenumber needs (`project`).
///
/// The minimum-norm particular solution, of all solutions `X` of the radial equation with source `s` the one with the least
/// `int X**2 d(R**2)` across the plasma (the one orthogonal to both homogeneous solutions), is a bounded right inverse, and the
/// convention that makes the perturbation series converge.
#[derive(Clone)]
pub struct ModeProjection {
    /// The homogeneous solution with unit value at `radial = 0` [dimensionless]
    pub unit_value: Array1<c64>,
    /// The homogeneous solution with unit slope at `radial = 0` [dimensionless]
    pub unit_slope: Array1<c64>,
    /// Square roots of the quadrature weights, times the mode's weight factors [metre]
    pub root_weights: Array1<f64>,
    /// `R[0, 0]` [metre]
    pub norm_1: f64,
    /// `Q[:, 0]` [dimensionless]
    pub direction_1: Array1<c64>,
    /// `R[0, 1]` [metre]
    pub overlap: c64,
    /// `R[1, 1]` [metre]
    pub norm_2: f64,
    /// `Q[:, 1]` [dimensionless]
    pub direction_2: Array1<c64>,
}

impl ModeProjection {
    /// # Arguments
    /// * `radial` - the radial variable
    /// * `k_max_squared_minus_k_squared` - the wavenumber's `k_max**2 - k_j**2`, real or complex [1 / metre ** 2]
    /// * `p_prime_term` - `(2 pi)**2 mu0 c_bar_p_prime / (psi_a - psi_b)` [1 / metre ** 4]
    /// * `weight_factors` - factors of the square roots of the quadrature weights, one per node: the norm minimised is
    ///   `int |X|**2 factor**2 d(R**2)`; `None` for `int |X|**2 d(R**2)` [dimensionless]
    pub fn new(radial: &RadialVariable, k_max_squared_minus_k_squared: c64, p_prime_term: f64, weight_factors: Option<ArrayView1<f64>>) -> ModeProjection {
        let n_radial: usize = radial.n_radial;
        let n_node: usize = radial.quadrature_r_squared.len();
        let zero_source: Array1<c64> = Array1::from_elem(n_radial, c64::new(0.0, 0.0));
        let one: c64 = c64::new(1.0, 0.0);
        let zero: c64 = c64::new(0.0, 0.0);
        let unit_value: Array1<c64> = solve_radial_ode(radial, zero_source.view(), k_max_squared_minus_k_squared, p_prime_term, one, zero);
        let unit_slope: Array1<c64> = solve_radial_ode(radial, zero_source.view(), k_max_squared_minus_k_squared, p_prime_term, zero, one);
        // Least squares min |sqrt(w) (forced + a U_1 + b U_2)| by a QR factorisation of [sqrt(w) U_1, sqrt(w) U_2] (Gram-Schmidt
        // twice), not by the 2 x 2 Gram (normal) equations, whose condition number is the square of R's: the growing homogeneous
        // solutions of a strongly hyperbolic mode are nearly parallel, and the normal equations lost all digits beyond about 18
        // e-folds of growth
        let mut root_weights: Array1<f64> = Array1::from_elem(n_node, f64::NAN);
        for i_node in 0..n_node {
            root_weights[i_node] = radial.quadrature_weights[i_node].sqrt();
            if let Some(factors) = weight_factors {
                root_weights[i_node] *= factors[i_node];
            }
        }
        let value_values: Array1<c64> = weighted_node_values(radial, unit_value.view(), root_weights.view());
        let slope_values: Array1<c64> = weighted_node_values(radial, unit_slope.view(), root_weights.view());
        // Hermitian inner products (conjugate the first factor), so that complex modes minimise int |X|**2 d(R**2)
        let norm_1: f64 = squared_norm(&value_values).sqrt();
        let direction_1: Array1<c64> = value_values.mapv(|value: c64| value / norm_1);
        let overlap_first: c64 = hermitian_inner(&direction_1, &slope_values);
        let mut remainder: Array1<c64> = Array1::from_elem(n_node, c64::new(f64::NAN, f64::NAN));
        for i_node in 0..n_node {
            remainder[i_node] = slope_values[i_node] - overlap_first * direction_1[i_node];
        }
        let overlap_again: c64 = hermitian_inner(&direction_1, &remainder);
        for i_node in 0..n_node {
            remainder[i_node] -= overlap_again * direction_1[i_node];
        }
        let overlap: c64 = overlap_first + overlap_again;
        let norm_2: f64 = squared_norm(&remainder).sqrt();
        let direction_2: Array1<c64> = remainder.mapv(|value: c64| value / norm_2);
        ModeProjection {
            unit_value,
            unit_slope,
            root_weights,
            norm_1,
            direction_1,
            overlap,
            norm_2,
            direction_2,
        }
    }

    /// # Arguments
    /// * `radial` - the radial variable
    /// * `forced` - coefficients in `radial` of a particular solution of this wavenumber [dimensionless]
    ///
    /// # Returns
    /// * the minimum-norm particular solution, `forced + a U_1 + b U_2` [dimensionless]
    pub fn project(&self, radial: &RadialVariable, forced: ArrayView1<c64>) -> Array1<c64> {
        let n_radial: usize = radial.n_radial;
        let forced_values: Array1<c64> = weighted_node_values(radial, forced, self.root_weights.view());
        // R (a, b) = -Q^H forced, with R = [[norm_1, overlap], [0, norm_2]]
        let projection_1: c64 = hermitian_inner(&self.direction_1, &forced_values);
        let projection_2: c64 = hermitian_inner(&self.direction_2, &forced_values);
        let weight_slope: c64 = -projection_2 / self.norm_2;
        let weight_value: c64 = (-projection_1 - self.overlap * weight_slope) / self.norm_1;
        let mut result: Array1<c64> = Array1::from_elem(n_radial, c64::new(f64::NAN, f64::NAN));
        for i_radial in 0..n_radial {
            result[i_radial] = forced[i_radial] + weight_value * self.unit_value[i_radial] + weight_slope * self.unit_slope[i_radial];
        }
        result
    }
}

/// The radial recursion of `solve_radial_ode` in double-double arithmetic, for a real `k_max**2 - k_j**2` and a real source.
///
/// # Arguments
/// * `radial` - the radial variable
/// * `forcing` - the recursion's forcing, as `solve_radial_ode` forms it from the source: in `R**2` the source's coefficients times
///   `(2 R_geo a_minor)**2` [metre ** 2]; in `ln(R**2 / R_c**2)` the coefficients of `w**2 (R_c**2 / 4) e**t s` [dimensionless]
/// * `k_max_squared_minus_k_squared` - `k_max**2 - k_j**2`, real [1 / metre ** 2]
/// * `p_prime_term` - `(2 pi)**2 mu0 c_bar_p_prime / (psi_a - psi_b)` [1 / metre ** 4]
/// * `value_0` - `X(radial = 0)` [dimensionless]
/// * `slope_0` - `dX/d(radial)(radial = 0)` [dimensionless]
///
/// # Returns
/// * coefficients of `X` in `radial`, `n_radial` of them [dimensionless]
fn recursion_extended(
    radial: &RadialVariable,
    forcing: &[f64],
    k_max_squared_minus_k_squared: f64,
    p_prime_term: f64,
    value_0: f64,
    slope_0: f64,
) -> Vec<DoubleDouble> {
    let n_radial: usize = radial.n_radial;
    let r_c_squared: f64 = radial.r_c_squared;
    let mut coefficients: Vec<DoubleDouble> = vec![DoubleDouble::ZERO; n_radial];
    coefficients[0] = DoubleDouble::from_float(value_0);
    coefficients[1] = DoubleDouble::from_float(slope_0);
    match radial.kind {
        RadialVariableKind::LogRSquared => {
            let log_half_width: f64 = radial.log_half_width;
            let exp_centre: f64 = radial.log_centre.exp();
            // w**2 (R_c**2 / 4) e**log_centre, the factor of the e**t terms
            let factor: f64 = log_half_width * log_half_width * 0.25 * r_c_squared * exp_centre;
            let coefficient_a: f64 = (k_max_squared_minus_k_squared - p_prime_term * r_c_squared) * factor;
            let coefficient_b: f64 = log_half_width * log_half_width * 0.25 * p_prime_term * r_c_squared * r_c_squared * (exp_centre * exp_centre);
            let mut products_a: Vec<DoubleDouble> = Vec::with_capacity(n_radial);
            let mut products_b: Vec<DoubleDouble> = Vec::with_capacity(n_radial);
            for i_radial in 0..n_radial - 2 {
                let power: f64 = i_radial as f64;
                // Cauchy products of d[0..m] with the series of exp(w radial) and exp(2 w radial), newest coefficient first
                products_a.clear();
                products_b.clear();
                for j_radial in 0..=i_radial {
                    products_a.push(coefficients[i_radial - j_radial].multiply_float(radial.exp_series[j_radial]));
                    products_b.push(coefficients[i_radial - j_radial].multiply_float(radial.exp2_series[j_radial]));
                }
                let convolution_a: DoubleDouble = sum_pairwise(&products_a);
                let convolution_b: DoubleDouble = sum_pairwise(&products_b);
                let mut term: DoubleDouble = DoubleDouble::from_float(forcing[i_radial]);
                term = term.add(coefficients[i_radial + 1].multiply_float(log_half_width * (power + 1.0)));
                term = term.add(convolution_a.multiply_float(coefficient_a).negate());
                term = term.add(convolution_b.multiply_float(coefficient_b).negate());
                coefficients[i_radial + 2] = term.divide_float((power + 1.0) * (power + 2.0));
            }
        }
        RadialVariableKind::RSquared => {
            let half_width: f64 = radial.r_squared_half_width;
            let half_width_squared: f64 = half_width * half_width;
            for i_radial in 0..n_radial - 2 {
                let power: f64 = i_radial as f64;
                let mut term: DoubleDouble = DoubleDouble::from_float(forcing[i_radial]);
                term = term.add(coefficients[i_radial + 1].multiply_float(4.0 * power * (power + 1.0) * half_width).negate());
                term = term.add(
                    coefficients[i_radial]
                        .multiply_float(k_max_squared_minus_k_squared * half_width_squared)
                        .negate(),
                );
                if i_radial >= 1 {
                    term = term.add(
                        coefficients[i_radial - 1]
                            .multiply_float(p_prime_term * half_width_squared * half_width)
                            .negate(),
                    );
                }
                coefficients[i_radial + 2] = term.divide_float(4.0 * r_c_squared * (power + 1.0) * (power + 2.0));
            }
        }
    }
    coefficients
}

/// The values of a double-double power series at the projection's Gauss-Legendre nodes, by Horner's rule in the radial variable, times
/// the square roots of the weights
fn weighted_node_values_extended(coefficients: &[DoubleDouble], nodes_radial: &[f64], root_weights: &[f64]) -> Vec<DoubleDouble> {
    let n_node: usize = nodes_radial.len();
    let n_radial: usize = coefficients.len();
    let mut values: Vec<DoubleDouble> = vec![DoubleDouble::ZERO; n_node];
    for i_node in 0..n_node {
        let mut accumulated: DoubleDouble = DoubleDouble::ZERO;
        for i_radial in (0..n_radial).rev() {
            accumulated = accumulated.multiply_float(nodes_radial[i_node]);
            accumulated = accumulated.add(coefficients[i_radial]);
        }
        values[i_node] = accumulated.multiply_float(root_weights[i_node]);
    }
    values
}

/// `sum first * second`, pairwise in double-double arithmetic
fn inner_extended(first: &[DoubleDouble], second: &[DoubleDouble]) -> DoubleDouble {
    let n_value: usize = first.len();
    let mut products: Vec<DoubleDouble> = Vec::with_capacity(n_value);
    for i_value in 0..n_value {
        products.push(first[i_value].multiply(second[i_value]));
    }
    sum_pairwise(&products)
}

/// The QR factors of one wavenumber's homogeneous solutions in double-double arithmetic (see `ModeProjection`)
struct ModeProjectionExtended {
    /// The homogeneous solution with unit value at `radial = 0` [dimensionless]
    unit_value: Vec<DoubleDouble>,
    /// The homogeneous solution with unit slope at `radial = 0` [dimensionless]
    unit_slope: Vec<DoubleDouble>,
    /// `R[0, 0]` [metre]
    norm_1: DoubleDouble,
    /// `Q[:, 0]` [dimensionless]
    direction_1: Vec<DoubleDouble>,
    /// `R[0, 1]` [metre]
    overlap: DoubleDouble,
    /// `R[1, 1]` [metre]
    norm_2: DoubleDouble,
    /// `Q[:, 1]` [dimensionless]
    direction_2: Vec<DoubleDouble>,
}

/// The minimum-norm particular solutions (see `ModeProjection`) in double-double arithmetic (about 32 digits), for strongly hyperbolic
/// wavenumbers with a real `k_max**2 - k_j**2` and a real source: the recursions, the values at the Gauss-Legendre nodes and the QR
/// projection keep `32 - growth / 2.3` digits, so wavenumbers whose radial functions grow by up to about 55 e-folds across the plasma keep
/// 8 or more digits, against none in double precision. The result is rounded to `f64`.
///
/// # Arguments
/// * `radial` - the radial variable
/// * `source_rows` - coefficients of `s` in `radial`, real, shape `(n_row, n_radial)` [1 / metre ** 2]
/// * `k_max_squared_minus_k_squared` - `k_max**2 - k_j**2` of each row, real [1 / metre ** 2]
/// * `p_prime_term` - `(2 pi)**2 mu0 c_bar_p_prime / (psi_a - psi_b)` [1 / metre ** 4]
///
/// # Returns
/// * coefficients of `X` in `radial`, shape `(n_row, n_radial)` [dimensionless]
pub fn min_norm_particular_extended(
    radial: &RadialVariable,
    source_rows: ArrayView2<f64>,
    k_max_squared_minus_k_squared: &[f64],
    p_prime_term: f64,
) -> Array2<f64> {
    let n_row: usize = source_rows.nrows();
    let n_radial: usize = radial.n_radial;
    let n_node: usize = radial.quadrature_r_squared.len();
    // The homogeneous solutions, their node values and their QR factors depend on k_max**2 - k_j**2 only: once per distinct value (a
    // Green's matrix has a row for every source power of the same wavenumber)
    let mut unique_k_max_squared_minus_k_squared: Vec<f64> = Vec::new();
    let mut row_mode: Vec<usize> = vec![0; n_row];
    for i_row in 0..n_row {
        let mut i_found: Option<usize> = None;
        let n_unique: usize = unique_k_max_squared_minus_k_squared.len();
        for i_unique in 0..n_unique {
            if unique_k_max_squared_minus_k_squared[i_unique] == k_max_squared_minus_k_squared[i_row] {
                i_found = Some(i_unique);
            }
        }
        match i_found {
            Some(i_unique) => row_mode[i_row] = i_unique,
            None => {
                row_mode[i_row] = unique_k_max_squared_minus_k_squared.len();
                unique_k_max_squared_minus_k_squared.push(k_max_squared_minus_k_squared[i_row]);
            }
        }
    }
    // The nodes in the radial variable, and the square roots of their weights, as `ModeProjection` uses them
    let mut nodes_radial: Vec<f64> = vec![f64::NAN; n_node];
    let mut root_weights: Vec<f64> = vec![f64::NAN; n_node];
    for i_node in 0..n_node {
        nodes_radial[i_node] = radial.of_r_squared(radial.quadrature_r_squared[i_node]);
        root_weights[i_node] = radial.quadrature_weights[i_node].sqrt();
    }
    let zero_forcing: Vec<f64> = vec![0.0; n_radial];

    // QR by Gram-Schmidt twice, as `ModeProjection`, per distinct k_max**2 - k_j**2
    let projections: Vec<ModeProjectionExtended> = unique_k_max_squared_minus_k_squared
        .par_iter()
        .map(|mode_k_max_squared_minus_k_squared: &f64| {
            let unit_value: Vec<DoubleDouble> = recursion_extended(radial, &zero_forcing, *mode_k_max_squared_minus_k_squared, p_prime_term, 1.0, 0.0);
            let unit_slope: Vec<DoubleDouble> = recursion_extended(radial, &zero_forcing, *mode_k_max_squared_minus_k_squared, p_prime_term, 0.0, 1.0);
            let value_values: Vec<DoubleDouble> = weighted_node_values_extended(&unit_value, &nodes_radial, &root_weights);
            let slope_values: Vec<DoubleDouble> = weighted_node_values_extended(&unit_slope, &nodes_radial, &root_weights);
            let norm_1: DoubleDouble = inner_extended(&value_values, &value_values).square_root();
            let mut direction_1: Vec<DoubleDouble> = vec![DoubleDouble::ZERO; n_node];
            for i_node in 0..n_node {
                direction_1[i_node] = value_values[i_node].divide(norm_1);
            }
            let overlap_first: DoubleDouble = inner_extended(&direction_1, &slope_values);
            let mut remainder: Vec<DoubleDouble> = vec![DoubleDouble::ZERO; n_node];
            for i_node in 0..n_node {
                remainder[i_node] = slope_values[i_node].add(overlap_first.multiply(direction_1[i_node]).negate());
            }
            let overlap_again: DoubleDouble = inner_extended(&direction_1, &remainder);
            for i_node in 0..n_node {
                remainder[i_node] = remainder[i_node].add(overlap_again.multiply(direction_1[i_node]).negate());
            }
            let overlap: DoubleDouble = overlap_first.add(overlap_again);
            let norm_2: DoubleDouble = inner_extended(&remainder, &remainder).square_root();
            let mut direction_2: Vec<DoubleDouble> = vec![DoubleDouble::ZERO; n_node];
            for i_node in 0..n_node {
                direction_2[i_node] = remainder[i_node].divide(norm_2);
            }
            ModeProjectionExtended {
                unit_value,
                unit_slope,
                norm_1,
                direction_1,
                overlap,
                norm_2,
                direction_2,
            }
        })
        .collect();

    // Every row's forced solution and its projection, the forcing formed from the source as `solve_radial_ode` forms it
    let half_width_squared: f64 = radial.r_squared_half_width * radial.r_squared_half_width;
    let factor: f64 = radial.log_half_width * radial.log_half_width * 0.25 * radial.r_c_squared * radial.log_centre.exp();
    let rows: Vec<Vec<f64>> = (0..n_row)
        .into_par_iter()
        .map(|i_row: usize| {
            let mut forcing: Vec<f64> = vec![f64::NAN; n_radial];
            for i_radial in 0..n_radial {
                match radial.kind {
                    RadialVariableKind::LogRSquared => {
                        // The source's Cauchy product with exp(w radial), then its factor
                        let mut source_with_exp: f64 = 0.0;
                        for j_radial in 0..=i_radial {
                            source_with_exp += source_rows[[i_row, j_radial]] * radial.exp_series[i_radial - j_radial];
                        }
                        forcing[i_radial] = source_with_exp * factor;
                    }
                    RadialVariableKind::RSquared => forcing[i_radial] = source_rows[[i_row, i_radial]] * half_width_squared,
                }
            }
            let forced: Vec<DoubleDouble> = recursion_extended(radial, &forcing, k_max_squared_minus_k_squared[i_row], p_prime_term, 0.0, 0.0);
            let forced_values: Vec<DoubleDouble> = weighted_node_values_extended(&forced, &nodes_radial, &root_weights);
            // R (a, b) = -Q^T forced, with R = [[norm_1, overlap], [0, norm_2]]
            let projection: &ModeProjectionExtended = &projections[row_mode[i_row]];
            let projection_1: DoubleDouble = inner_extended(&projection.direction_1, &forced_values);
            let projection_2: DoubleDouble = inner_extended(&projection.direction_2, &forced_values);
            let weight_slope: DoubleDouble = projection_2.divide(projection.norm_2).negate();
            let weight_value: DoubleDouble = projection_1
                .negate()
                .add(projection.overlap.multiply(weight_slope).negate())
                .divide(projection.norm_1);
            let mut result: Vec<f64> = vec![f64::NAN; n_radial];
            for i_radial in 0..n_radial {
                let with_value: DoubleDouble = forced[i_radial].add(weight_value.multiply(projection.unit_value[i_radial]));
                result[i_radial] = with_value.add(weight_slope.multiply(projection.unit_slope[i_radial])).to_float();
            }
            result
        })
        .collect();
    let mut result: Array2<f64> = Array2::from_elem((n_row, n_radial), f64::NAN);
    for i_row in 0..n_row {
        for i_radial in 0..n_radial {
            result[[i_row, i_radial]] = rows[i_row][i_radial];
        }
    }
    result
}

/// The fewest terms of a radial power series whose last `N_RADIAL_TAIL` powers, and every later run of that many, change it on the
/// plasma by at most `radial_tolerance`: among the powers given when they reach it, else beyond them, the decay of their last two runs
/// continued (geometric, the decay of the `r_squared` series; an over-count for the faster decay of the `log_r_squared` series).
///
/// # Arguments
/// * `power_sizes` - the bound on each power's part of the series on the plasma (`lattice::series_power_sizes`), relative to the
///   series' value on the magnetic axis, at least `N_RADIAL_MIN` powers [dimensionless]
/// * `radial_tolerance` - the largest change of the series from its last `N_RADIAL_TAIL` powers, positive [dimensionless]
///
/// # Returns
/// * the number of terms, at least `N_RADIAL_MIN`; `None` when the last two runs do not decay [dimensionless]
pub fn radial_terms_needed(power_sizes: &Array1<f64>, radial_tolerance: f64) -> Option<usize> {
    let n_power: usize = power_sizes.len();
    // tails[n] is the change from the last N_RADIAL_TAIL powers of n terms
    let mut tails: Array1<f64> = Array1::from_elem(n_power + 1, f64::NAN);
    for n_term in N_RADIAL_TAIL..=n_power {
        let mut tail: f64 = 0.0;
        for i_radial in (n_term - N_RADIAL_TAIL)..n_term {
            tail += power_sizes[i_radial];
        }
        tails[n_term] = tail;
    }
    // The last run above the tolerance; NaN propagates: a tail that cannot be evaluated is not a small one
    let mut n_term_above: usize = 0;
    for n_term in (N_RADIAL_TAIL..=n_power).rev() {
        if !(tails[n_term] <= radial_tolerance) {
            n_term_above = n_term;
            break;
        }
    }
    if n_term_above < n_power {
        return Some((n_term_above + 1).max(N_RADIAL_MIN));
    }
    // Beyond the powers given: the decay of the last two runs, continued
    let ratio: f64 = tails[n_power] / tails[n_power - N_RADIAL_TAIL];
    if !(ratio > 0.0 && ratio < 1.0) {
        return None;
    }
    let n_run: f64 = (radial_tolerance / tails[n_power]).ln() / ratio.ln();
    Some(n_power.saturating_add((n_run * N_RADIAL_TAIL as f64).ceil() as usize))
}
